import fs from "node:fs";
import path from "node:path";
import matter from "gray-matter";
import { marked } from "marked";

export type Book = {
  slug: string;
  title: string;
  author: string;
  year: number;
  rating: number;
  tags: string[];
};

const dir = path.join(process.cwd(), "content", "books");

function read(file: string) {
  const { data, content } = matter(fs.readFileSync(path.join(dir, file), "utf8"));
  const book: Book = {
    slug: file.replace(/\.md$/, ""),
    title: String(data.title),
    author: String(data.author),
    year: Number(data.year),
    rating: Number(data.rating),
    tags: (data.tags ?? []).map(String),
  };
  return { book, content };
}

export function getBooks(): Book[] {
  return fs
    .readdirSync(dir)
    .filter((f) => f.endsWith(".md"))
    .map((f) => read(f).book)
    .sort((a, b) => a.title.localeCompare(b.title, "en"));
}

export function getBook(slug: string) {
  if (!/^[a-z0-9-]+$/i.test(slug) || !fs.existsSync(path.join(dir, slug + ".md"))) return null;
  const { book, content } = read(slug + ".md");
  return { book, html: marked.parse(content, { async: false }) as string };
}

export function topRated(n: number): Book[] {
  return getBooks()
    .sort((a, b) => b.rating - a.rating || a.title.localeCompare(b.title, "en"))
    .slice(0, n);
}
