import type { Metadata } from "next";
import Link from "next/link";
import { notFound } from "next/navigation";
import { getBook } from "@/lib/books";
import FavoriteButton from "./favorite-button";

export async function generateMetadata({ params }: PageProps<"/books/[slug]">): Promise<Metadata> {
  const { slug } = await params;
  const r = getBook(slug);
  return { title: r ? `${r.book.title} | Bookshelf` : "Not found | Bookshelf" };
}

export default async function BookPage({ params }: PageProps<"/books/[slug]">) {
  const { slug } = await params;
  const r = getBook(slug);
  if (!r) notFound();
  const { book, html } = r;
  return (
    <article>
      <h1>{book.title}</h1>
      <p>by {book.author}</p>
      <p>Published in {book.year}</p>
      <p>Rating: {book.rating}/5</p>
      <div>
        {book.tags.map((t) => (
          <Link key={t} href="/books" style={{ marginRight: 8 }}>
            {t}
          </Link>
        ))}
      </div>
      <div dangerouslySetInnerHTML={{ __html: html }} />
      <FavoriteButton slug={book.slug} />
    </article>
  );
}
